test('Adversarial 2.1: Midnight representations: "0h", "00:00", "24h"', () => {
  const res0h = parseVietnameseTaskInput('Chốt sổ 0h ngày mai', ANCHOR);
  assert.equal(res0h.dueTime, '00:00');

  const res00 = parseVietnameseTaskInput('Chốt sổ 00:00 ngày mai', ANCHOR);
  assert.equal(res00.dueTime, '00:00');

  const res24h = parseVietnameseTaskInput('Chốt sổ 24h ngày mai', ANCHOR);
  assert.equal(res24h.dueTime, '00:00');
});

test('Adversarial 2.2: Midnight phrase "12 giờ đêm" / "12h đêm" defect analysis', () => {
  // In Vietnamese culture: "12 giờ đêm" is 00:00 (midnight), while "12 giờ trưa" is 12:00 (noon).
  const resTrua = parseVietnameseTaskInput('Ăn cơm 12 giờ trưa', ANCHOR);
  assert.equal(resTrua.dueTime, '12:00');

  const resDem = parseVietnameseTaskInput('Nộp bài 12 giờ đêm', ANCHOR);
  // DOCUMENTED DEFECT: line 421 in tasks-engine.ts has `period === 'đêm' && h < 12`.
  // When h === 12, h is NOT < 12, so h remains 12, resulting in "12:00" instead of "00:00"!
  assert.equal(resDem.dueTime, '12:00', 'Confirmed flaw: "12 giờ đêm" parses as 12:00 noon instead of 00:00 midnight');
});

test('Adversarial 2.3: Invalid minute values (e.g., "14h89", "23:75")', () => {
  // Parser does not validate m < 60!
  const resInvalidMin = parseVietnameseTaskInput('Họp lúc 14h89', ANCHOR);
  // DOCUMENTED DEFECT: produces "14:89" which is an invalid ISO time string
  assert.equal(resInvalidMin.dueTime, '14:89', 'Confirmed flaw: parser produces invalid minute "14:89" without m < 60 clamp');
});

