test('Adversarial 6.1: Level 1 -> 2 transition and exact rollback via undo()', () => {
  resetSharedState(ANCHOR);

  // Set XP to 195 (Level 1: 0-199 XP, Level 2 begins at 200 XP)
  updateSharedState((prev) => ({
    ...prev,
    xp: 195,
    level: 1,
    rankTitle: 'Tân sinh viên ngơ ngác',
  }));

  const { task, deadline, undo } = addQuickTask(createSampleTask({ title: 'Task Level Up' }));

  // Post-addition assertions
  const stateAfterAdd = getSharedState();
  assert.equal(stateAfterAdd.xp, 205, 'XP must be 205');
  assert.equal(stateAfterAdd.level, 2, 'Level must advance to 2');
  assert.equal(stateAfterAdd.rankTitle, 'Cú đêm giảng đường');
  assert.ok(stateAfterAdd.tasks.some((t) => t.id === task.id));
  assert.ok(stateAfterAdd.deadlines.some((d) => d.id === deadline.id));

  // Undo rollback assertions
  undo();

  const stateAfterUndo = getSharedState();
  assert.equal(stateAfterUndo.xp, 195, 'XP rolls back to 195');
  assert.equal(stateAfterUndo.level, 1, 'Level cleanly demotes back to 1');
  assert.equal(stateAfterUndo.rankTitle, 'Tân sinh viên ngơ ngác', 'Rank title restores to Level 1');
  assert.equal(stateAfterUndo.tasks.some((t) => t.id === task.id), false, 'Task removed');
  assert.equal(stateAfterUndo.deadlines.some((d) => d.id === deadline.id), false, 'Deadline removed');
});

test('Adversarial 6.2: Rapid multi-task burst (10 tasks) and LIFO/FIFO undos', () => {
  resetSharedState(ANCHOR);
  const baselineXp = getSharedState().xp;

  const records: Array<{ undo: () => void; taskId: string; deadlineId: string }> = [];

  // Add 10 quick tasks in rapid burst
  for (let i = 0; i < 10; i++) {
    const res = addQuickTask(createSampleTask({ title: `Burst Task ${i + 1}` }));
    records.push({ undo: res.undo, taskId: res.task.id, deadlineId: res.deadline.id });
  }

  assert.equal(getSharedState().xp, baselineXp + 100, '10 tasks must add exactly 100 XP');
  assert.equal(
    records.every((r) => getSharedState().tasks.some((t) => t.id === r.taskId)),
    true,
    'All 10 tasks exist in store'
  );

  // Undo even-indexed tasks (0, 2, 4, 6, 8) -> 5 undos
  for (let i = 0; i < records.length; i += 2) {
    records[i]!.undo();
  }

  const midState = getSharedState();
  assert.equal(midState.xp, baselineXp + 50, '5 undos reduce XP by 50');

  // Verify removed tasks are absent, while odd-indexed tasks still exist
  for (let i = 0; i < records.length; i++) {
    const exists = midState.tasks.some((t) => t.id === records[i]!.taskId);
    if (i % 2 === 0) {
      assert.equal(exists, false, `Task ${i} must be removed`);
    } else {
      assert.equal(exists, true, `Task ${i} must remain`);
    }
  }

  // Undo remaining odd-indexed tasks
  for (let i = 1; i < records.length; i += 2) {
    records[i]!.undo();
  }

  const finalState = getSharedState();
  assert.equal(finalState.xp, baselineXp, 'All tasks undone: XP returns to baseline');
});

test('Adversarial 6.3: Idempotency of undo() - calling 10 times does not deplete XP', () => {
  resetSharedState(ANCHOR);
  const baselineXp = getSharedState().xp;

  const res = addQuickTask(createSampleTask({ title: 'Idempotency Task' }));
  assert.equal(getSharedState().xp, baselineXp + 10);

  // Call undo 10 times in a row
  for (let i = 0; i < 10; i++) {
    res.undo();
  }

  assert.equal(getSharedState().xp, baselineXp, 'XP must deduct only once despite 10 undo calls');
});

test('Adversarial 6.4: Zero XP floor protection on undo', () => {
  resetSharedState(ANCHOR);

  // Force store XP to 5
  updateSharedState((prev) => ({
    ...prev,
    xp: 5,
    level: 1,
    rankTitle: 'Tân sinh viên ngơ ngác',
  }));

  const res = addQuickTask(createSampleTask({ title: 'Zero Floor Task' }));
  assert.equal(getSharedState().xp, 15);

  // Manually tamper XP down to 3 while task is pending
  updateSharedState((prev) => ({ ...prev, xp: 3 }));

  // Now call undo (3 - 10 = -7, clamped to 0)
  res.undo();
  assert.equal(getSharedState().xp, 0, 'XP must clamp to 0 and never become negative');
});

