test('Adversarial 7.1: Event campusos:deadline-created dispatch detail contract', () => {
  let capturedDetail: any = null;

  const listener = (e: Event) => {
    capturedDetail = (e as CustomEvent).detail;
  };

  if (typeof window !== 'undefined') {
    window.addEventListener('campusos:deadline-created', listener);
  }

  const res = addQuickTask(createSampleTask({ title: 'Event Bus Contract Task' }));

  if (typeof window !== 'undefined') {
    window.removeEventListener('campusos:deadline-created', listener);
    assert.ok(capturedDetail, 'Event must be dispatched');
    assert.ok(capturedDetail.deadline, 'Detail contains deadline object');
    assert.ok(capturedDetail.task, 'Detail contains task object');
    assert.equal(capturedDetail.deadline.id, res.deadline.id);
  }
});
